import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Administrator Guide","description":"","frontmatter":{},"headers":[],"relativePath":"admin/overview.md","filePath":"admin/overview.md"}'),r={name:"admin/overview.md"};function o(s,e,l,d,c,g){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="administrator-guide" tabindex="-1">Administrator Guide <a class="header-anchor" href="#administrator-guide" aria-label="Permalink to &quot;Administrator Guide&quot;">​</a></h1><p>The FOSSBilling Administrator Portal is your central hub for managing your hosting business. It provides tools to automate service delivery, manage financial records, and provide customer support.</p><hr><h2 id="🚀-getting-started-as-an-admin" tabindex="-1">🚀 Getting Started as an Admin <a class="header-anchor" href="#🚀-getting-started-as-an-admin" aria-label="Permalink to &quot;🚀 Getting Started as an Admin&quot;">​</a></h2><p>Once you have installed FOSSBilling, log in to the Admin Portal at <code>http://localhost:3000</code>. The default credentials (if seeded) are <code>admin@fossbilling.org</code> / <code>admin123</code>.</p><div class="tip custom-block"><p class="custom-block-title">Comprehensive End-to-End Walkthrough</p><p>For the complete step-by-step guide with diagrams and screenshots, see the <strong><a href="/guide/step-by-step-guide">Complete Step-by-Step Usage Guide</a></strong>.</p></div><h3 id="essential-setup-checklist" tabindex="-1">Essential Setup Checklist <a class="header-anchor" href="#essential-setup-checklist" aria-label="Permalink to &quot;Essential Setup Checklist&quot;">​</a></h3><ol><li><strong><a href="/admin/company">Company Profile</a>:</strong> Set your company name, logo, support email, phone, physical address, and Tax ID.</li><li><strong>Currencies &amp; Exchange Rates:</strong> Define your base currency (e.g. USD, EUR, IDR) and automatic exchange rates.</li><li><strong><a href="/admin/payment-gateways">Payment Gateways</a>:</strong> Enable Stripe, PayPal Express, Midtrans (QRIS/VA), or Offline Bank Wire.</li><li><strong><a href="/admin/servers">Server Nodes</a>:</strong> Connect remote servers (cPanel, HestiaCP, Plesk, DirectAdmin, CWP) with API tokens and test connectivity.</li><li><strong><a href="/admin/domain-registrars">Domain Registrars</a>:</strong> Configure live registrar APIs (Namecheap, ResellerClub, Internet.bs).</li><li><strong><a href="/admin/products">Products &amp; Packages</a>:</strong> Create shared hosting plans, domain pricing tables, license keys, and digital downloads.</li><li><strong><a href="/admin/email-templates">Email Templates</a>:</strong> Customize automated order confirmations, welcome emails, invoice notices, and dunning reminders.</li></ol><hr><h2 id="📊-the-dashboard-daily-workflow" tabindex="-1">📊 The Dashboard &amp; Daily Workflow <a class="header-anchor" href="#📊-the-dashboard-daily-workflow" aria-label="Permalink to &quot;📊 The Dashboard &amp; Daily Workflow&quot;">​</a></h2><p>Your command center for real-time monitoring and day-to-day operations:</p><ul><li><strong>Revenue Overview:</strong> Track Monthly Recurring Revenue (MRR), total gross revenue, and pending invoice totals.</li><li><strong>Client Activity:</strong> Real-time stream of new client registrations, logins, and geographic distribution.</li><li><strong>Operational Queue:</strong> Quick badges for pending orders requiring manual verification, unpaid overdue invoices, and urgent open support tickets.</li><li><strong>System Diagnostics:</strong> Live health monitoring of the Go REST API engine, Redis caching latency, and background worker scheduler.</li></ul><hr><h2 id="👥-client-lifecycle-management" tabindex="-1">👥 Client Lifecycle Management <a class="header-anchor" href="#👥-client-lifecycle-management" aria-label="Permalink to &quot;👥 Client Lifecycle Management&quot;">​</a></h2><p>Manage customer accounts from initial registration through subscription renewals:</p><ul><li><strong>Client Profiles:</strong> View and edit client contact info, company details, currency preference, and tax exemption status.</li><li><strong>Prepay Balance &amp; Credits:</strong> Add manual account balance credits (<code>+$100.00</code>), adjust promotional funds, or issue store credit for returns.</li><li><strong>Service Subscriptions:</strong> View all active, suspended, or canceled hosting accounts, domains, and licenses tied to a client.</li><li><strong>Security &amp; Audit Trail:</strong> Inspect client login IPs, user-agent fingerprints, failed login attempts, and password reset requests.</li><li><strong>Internal Staff Notes:</strong> Keep confidential staff notes and account history logs visible only to administrators.</li></ul><hr><h2 id="🧾-billing-tax-invoicing-operations" tabindex="-1">🧾 Billing, Tax &amp; Invoicing Operations <a class="header-anchor" href="#🧾-billing-tax-invoicing-operations" aria-label="Permalink to &quot;🧾 Billing, Tax &amp; Invoicing Operations&quot;">​</a></h2><p>Automated and manual financial control:</p><ul><li><strong>Recurring Invoices:</strong> The background daemon scans subscriptions and generates renewal invoices 14 days in advance.</li><li><strong>Instant Prepay Settlement:</strong> Invoices automatically settle if the customer holds sufficient prepaid credit balance.</li><li><strong>Tax Rules &amp; VAT Engine:</strong> Configure multi-tier tax rates based on country, state/province, or European Union reverse-charge VAT rules.</li><li><strong>Refunds &amp; Dispute Handling:</strong> Issue 1-click full or partial refunds directly back to Stripe/PayPal or credit the customer&#39;s on-platform balance.</li><li><strong>Automated Dunning Reminders:</strong> Configurable reminders sent 3 days before due date, on due date, and 3 days post due date.</li><li><strong>Overdue Suspension:</strong> Automated remote service suspension via server API at 7 days overdue, with instant auto-reactivation upon invoice payment.</li></ul><hr><h2 id="🎧-support-helpdesk-administration" tabindex="-1">🎧 Support Helpdesk Administration <a class="header-anchor" href="#🎧-support-helpdesk-administration" aria-label="Permalink to &quot;🎧 Support Helpdesk Administration&quot;">​</a></h2><p>Deliver enterprise support:</p><ul><li><strong>Department Routing:</strong> Create specialized departments (e.g. Sales, L1 Tech Support, L2 Cloud Engineering, Billing).</li><li><strong>Ticket Escalation &amp; Assignment:</strong> Assign tickets to specific operators or teams.</li><li><strong>Canned Responses:</strong> Accelerate resolution with pre-written templates and variable placeholders.</li><li><strong>Staff-Only Internal Notes:</strong> Collaborate with colleagues directly inside the ticket thread without exposing internal discussion to the client.</li></ul><hr><h2 id="🛠️-system-tools-cli-administration" tabindex="-1">🛠️ System Tools &amp; CLI Administration <a class="header-anchor" href="#🛠️-system-tools-cli-administration" aria-label="Permalink to &quot;🛠️ System Tools &amp; CLI Administration&quot;">​</a></h2><ul><li><strong>Activity &amp; Audit Logs:</strong> Comprehensive logging of all administrator actions (deletions, modifications, logins, impersonations).</li><li><strong>Cron Worker Management:</strong> Monitor background worker executions or manually trigger billing cycles via <code>./backend-go/bin/cli cron:run</code>.</li><li><strong>Cache Management:</strong> Invalidate Redis cache keys across servers when modifying templates or global configurations.</li><li><strong>Mass Mail Broadcasting:</strong> Send system maintenance advisories or marketing updates with markdown formatting and variable substitution.</li></ul>',27)])])}const p=t(r,[["render",o]]);export{m as __pageData,p as default};
